const { scrypt, randomBytes, timingSafeEqual } = require('node:crypto');
const { promisify } = require('node:util');

const scryptAsync = promisify(scrypt);

// OWASP minimum for scrypt. Parameters are stored in each hash, so they can be
// raised later without invalidating existing passwords.
const PARAMS = { N: 2 ** 17, r: 8, p: 1 };
const KEY_LEN = 32;
const SALT_LEN = 16;

function derive(password, salt, { N, r, p }, keyLen) {
  // scrypt needs 128 * N * r bytes, which exceeds Node's 32 MiB default.
  return scryptAsync(password.normalize('NFKC'), salt, keyLen, { N, r, p, maxmem: 256 * N * r });
}

async function hashPassword(password) {
  const salt = randomBytes(SALT_LEN);
  const key = await derive(password, salt, PARAMS, KEY_LEN);
  const { N, r, p } = PARAMS;
  return ['scrypt', N, r, p, salt.toString('base64'), key.toString('base64')].join('$');
}

async function verifyPassword(password, stored) {
  const [scheme, N, r, p, salt, key] = stored.split('$');
  if (scheme !== 'scrypt') return false;
  const expected = Buffer.from(key, 'base64');
  const actual = await derive(
    password,
    Buffer.from(salt, 'base64'),
    { N: Number(N), r: Number(r), p: Number(p) },
    expected.length
  );
  return timingSafeEqual(actual, expected);
}

module.exports = { hashPassword, verifyPassword };

// Fixed-window attempt counter. In-memory, so it only works for a single
// process; swap the Map for Redis (INCR + EXPIRE) when running several.
function createLimiter({ limit, windowMs }) {
  const entries = new Map(); // key -> { count, resetAt }

  const sweep = setInterval(() => {
    const now = Date.now();
    for (const [key, entry] of entries) {
      if (entry.resetAt <= now) entries.delete(key);
    }
  }, windowMs);
  sweep.unref();

  return {
    // Records an attempt. Returns 0 if it is allowed, otherwise the number of
    // seconds until the window resets.
    consume(key) {
      const now = Date.now();
      let entry = entries.get(key);
      if (!entry || entry.resetAt <= now) {
        entry = { count: 0, resetAt: now + windowMs };
        entries.set(key, entry);
      }
      entry.count++;
      return entry.count > limit ? Math.ceil((entry.resetAt - now) / 1000) : 0;
    },

    // Gives back one attempt (used when the attempt turned out not to be a failure).
    refund(key) {
      const entry = entries.get(key);
      if (entry && entry.count > 0) entry.count--;
    },

    reset(key) {
      entries.delete(key);
    },
  };
}

module.exports = { createLimiter };

const { randomBytes, randomUUID } = require('node:crypto');
const express = require('express');
const session = require('express-session');
const { hashPassword, verifyPassword } = require('./passwords');
const { createLimiter } = require('./rateLimit');

const WINDOW_MS = 15 * 60 * 1000;
const MAX_FAILS_PER_USERNAME = 5;
const MAX_FAILS_PER_IP = 20;
const SESSION_TTL_MS = 60 * 60 * 1000;
const MIN_PASSWORD_LEN = 8;
const MAX_PASSWORD_LEN = 1024;
const MAX_USERNAME_LEN = 64;

const normalizeUsername = (username) => username.trim().toLowerCase();

function createApp({ sessionSecret, trustProxy = false }) {
  const app = express();
  const production = app.get('env') === 'production';

  // Behind a reverse proxy this must be set, or req.ip is the proxy's address
  // and every client shares one rate-limit bucket.
  app.set('trust proxy', trustProxy);
  app.disable('x-powered-by');
  app.use(express.json({ limit: '10kb' }));

  app.use(
    session({
      name: 'sid',
      secret: sessionSecret,
      resave: false,
      saveUninitialized: false,
      rolling: true,
      // Default MemoryStore leaks and is per-process; use connect-redis or
      // similar in production.
      cookie: {
        httpOnly: true,
        sameSite: 'lax',
        secure: production,
        maxAge: SESSION_TTL_MS,
      },
    })
  );

  // Replace with a real database. username -> { id, username, passwordHash }
  const users = new Map();

  const failsByUsername = createLimiter({ limit: MAX_FAILS_PER_USERNAME, windowMs: WINDOW_MS });
  const failsByIp = createLimiter({ limit: MAX_FAILS_PER_IP, windowMs: WINDOW_MS });

  // Verified against when the username doesn't exist, so unknown and known
  // usernames take the same time to reject.
  const dummyHash = hashPassword(randomBytes(16).toString('hex'));

  function readCredentials(body) {
    const { username, password } = body ?? {};
    if (typeof username !== 'string' || typeof password !== 'string') return null;
    const name = normalizeUsername(username);
    if (!name || name.length > MAX_USERNAME_LEN) return null;
    if (!password || password.length > MAX_PASSWORD_LEN) return null;
    return { username: name, password };
  }

  function tooManyAttempts(res, retryAfter) {
    res.set('Retry-After', String(retryAfter));
    res.status(429).json({ error: 'Too many failed attempts. Try again later.' });
  }

  function requireAuth(req, res, next) {
    if (!req.session.userId) return res.status(401).json({ error: 'Not authenticated' });
    next();
  }

  app.post('/register', async (req, res, next) => {
    try {
      const creds = readCredentials(req.body);
      if (!creds || creds.password.length < MIN_PASSWORD_LEN) {
        return res.status(400).json({
          error: `Username and a password of at least ${MIN_PASSWORD_LEN} characters are required`,
        });
      }
      if (users.has(creds.username)) {
        return res.status(409).json({ error: 'Username is taken' });
      }
      const passwordHash = await hashPassword(creds.password);
      // Re-check: another request may have registered the name while hashing.
      if (users.has(creds.username)) {
        return res.status(409).json({ error: 'Username is taken' });
      }
      users.set(creds.username, { id: randomUUID(), username: creds.username, passwordHash });
      res.status(201).json({ username: creds.username });
    } catch (err) {
      next(err);
    }
  });

  app.post('/login', async (req, res, next) => {
    try {
      const creds = readCredentials(req.body);
      if (!creds) {
        return res.status(400).json({ error: 'Username and password are required' });
      }

      // Attempts are counted before the password is checked and refunded on
      // success. Counting only after a failure would let a burst of parallel
      // requests all pass the check before any of them is recorded.
      const ipRetry = failsByIp.consume(req.ip);
      if (ipRetry) return tooManyAttempts(res, ipRetry);
      const userRetry = failsByUsername.consume(creds.username);
      if (userRetry) return tooManyAttempts(res, userRetry);

      const user = users.get(creds.username);
      const ok = await verifyPassword(creds.password, user ? user.passwordHash : await dummyHash);
      if (!user || !ok) {
        return res.status(401).json({ error: 'Invalid username or password' });
      }

      failsByIp.refund(req.ip);
      failsByUsername.reset(creds.username);

      // New session ID on privilege change, to prevent session fixation.
      req.session.regenerate((err) => {
        if (err) return next(err);
        req.session.userId = user.id;
        req.session.username = user.username;
        res.json({ username: user.username });
      });
    } catch (err) {
      next(err);
    }
  });

  app.post('/logout', (req, res, next) => {
    req.session.destroy((err) => {
      if (err) return next(err);
      res.clearCookie('sid');
      res.status(204).end();
    });
  });

  app.get('/me', requireAuth, (req, res) => {
    res.json({ id: req.session.userId, username: req.session.username });
  });

  app.use((err, req, res, next) => {
    if (err.type === 'entity.parse.failed' || err.type === 'entity.too.large') {
      return res.status(err.status).json({ error: 'Invalid request body' });
    }
    console.error(err);
    res.status(500).json({ error: 'Internal server error' });
  });

  return app;
}

module.exports = { createApp, MAX_FAILS_PER_USERNAME };

