const { test, before, after } = require('node:test');
const assert = require('node:assert/strict');
const { createApp, MAX_FAILS_PER_USERNAME } = require('../src/app');

let server;
let base;

const post = (path, body, cookie) =>
  fetch(base + path, {
    method: 'POST',
    headers: { 'content-type': 'application/json', ...(cookie && { cookie }) },
    body: JSON.stringify(body),
  });

const cookieOf = (res) => res.headers.get('set-cookie').split(';')[0];

before(async () => {
  server = createApp({ sessionSecret: 'test-secret-test-secret-test-secret' }).listen(0);
  base = `http://127.0.0.1:${server.address().port}`;
  await post('/register', { username: 'alice', password: 'correct horse' });
  await post('/register', { username: 'bob', password: 'battery staple' });
});

after(() => server.close());

test('login creates a session, logout ends it', async () => {
  assert.equal((await fetch(base + '/me')).status, 401);

  const login = await post('/login', { username: 'Alice', password: 'correct horse' });
  assert.equal(login.status, 200);
  const cookie = cookieOf(login);
  assert.match(login.headers.get('set-cookie'), /HttpOnly/);

  const me = await fetch(base + '/me', { headers: { cookie } });
  assert.equal((await me.json()).username, 'alice');

  assert.equal((await post('/logout', {}, cookie)).status, 204);
  assert.equal((await fetch(base + '/me', { headers: { cookie } })).status, 401);
});

test('session ID changes on login', async () => {
  const first = cookieOf(await post('/login', { username: 'alice', password: 'correct horse' }));
  const second = cookieOf(await post('/login', { username: 'alice', password: 'correct horse' }, first));
  assert.notEqual(first, second);
  assert.equal((await fetch(base + '/me', { headers: { cookie: first } })).status, 401);
});

test('wrong password and unknown user get the same response', async () => {
  const wrong = await post('/login', { username: 'alice', password: 'nope' });
  const unknown = await post('/login', { username: 'nobody', password: 'nope' });
  assert.equal(wrong.status, 401);
  assert.equal(unknown.status, 401);
  assert.deepEqual(await wrong.json(), await unknown.json());
});

test('parallel failed attempts are limited, and the correct password is then refused too', async () => {
  const attempts = await Promise.all(
    Array.from({ length: MAX_FAILS_PER_USERNAME + 3 }, () =>
      post('/login', { username: 'bob', password: 'wrong' })
    )
  );
  const statuses = attempts.map((r) => r.status);
  assert.equal(statuses.filter((s) => s === 401).length, MAX_FAILS_PER_USERNAME);
  assert.equal(statuses.filter((s) => s === 429).length, 3);

  const locked = await post('/login', { username: 'bob', password: 'battery staple' });
  assert.equal(locked.status, 429);
  assert.ok(Number(locked.headers.get('retry-after')) > 0);
});

